import type { Lesson, Localized } from '../types';
import { sd1Week2LessonsB } from './lessonsB';

/** Short helper: one string in English, Spanish, and Portuguese. */
const L = (en: string, es: string, pt: string): Localized => ({ en, es, pt });

/**
 * Software Development 1, Week 2: requirements engineering, from the first
 * complaint to a user story with acceptance criteria. Every example is
 * written for this site with everyday products: a public library, a gym, a food
 * delivery app.
 */
const lessonsA: Lesson[] = [
  {
    id: 'sd1w2-l1-what-is-a-requirement',
    title: L('What a requirement is, and why it comes first', 'Qué es un requisito y por qué va primero', 'O que é um requisito e por que ele vem primeiro'),
    minutes: 20,
    diagram: 'lifecycle',
    body: [
      L('A requirement is a condition or capability that a system must have so that a user can reach a goal, or so that it satisfies a contract, a law, or a standard. It describes what the system must do or how well it must do it, never how the code will do it. Compare a bad and a good version. Bad: "the library app stores loans in a MySQL table and calls a REST endpoint to renew them" (that names a database and a backend: it is how). Good: "a reader can renew a loan up to 2 times, unless another reader is waiting for the book" (a capability the user gets: it is what). The bad version also hides the real rule.',
        'Un requisito es una condición o capacidad que un sistema debe tener para que un usuario alcance un objetivo, o para cumplir un contrato, una ley o una norma. Describe qué debe hacer el sistema o qué tan bien debe hacerlo, nunca cómo lo hará el código. Compara una versión mala y una buena. Mala: "la app de la biblioteca guarda los préstamos en una tabla MySQL y llama a un endpoint REST para renovarlos" (nombra una base de datos y un backend: es el cómo). Buena: "un lector puede renovar un préstamo hasta 2 veces, salvo que otro lector esté esperando el libro" (una capacidad que obtiene el usuario: es el qué). La versión mala además esconde la regla real.',
        'Um requisito é uma condição ou capacidade que um sistema precisa ter para que um usuário alcance um objetivo, ou para cumprir um contrato, uma lei ou uma norma. Ele descreve o que o sistema deve fazer ou quão bem deve fazer, nunca como o código vai fazer. Compare uma versão ruim e uma boa. Ruim: "o app da biblioteca guarda os empréstimos numa tabela MySQL e chama um endpoint REST para renová-los" (cita um banco de dados e um backend: é o como). Boa: "um leitor pode renovar um empréstimo até 2 vezes, a menos que outro leitor esteja esperando o livro" (uma capacidade que o usuário ganha: é o quê). A versão ruim ainda esconde a regra real.'),
      L('Clients rarely hand you requirements. They hand you a problem statement: "readers wait months for popular books, yet reserved copies sit uncollected on our hold shelf". Detecting a problem is not the same as understanding it. Ask why it happens. Maybe readers are told by a letter that arrives late (cause A), maybe they reserved weeks ago and forgot (cause B), maybe there is no easy way to cancel a reservation they no longer want, so the copy waits for nobody (cause C). Each cause leads to a different solution: instant notifications, reminders, or one-tap cancellation. Requirements come from the causes you choose to attack.',
        'Los clientes casi nunca te entregan requisitos. Te entregan un planteamiento del problema: "los lectores esperan meses por los libros populares, pero los ejemplares reservados se quedan sin retirar en nuestro estante de reservas". Detectar un problema no es lo mismo que entenderlo. Pregunta por qué ocurre. Tal vez a los lectores se les avisa con una carta que llega tarde (causa A), tal vez reservaron hace semanas y lo olvidaron (causa B), tal vez no hay una forma fácil de cancelar una reserva que ya no quieren y el ejemplar espera a nadie (causa C). Cada causa lleva a una solución distinta: avisos instantáneos, recordatorios o cancelación con un toque. Los requisitos salen de las causas que decides atacar.',
        'Clientes quase nunca entregam requisitos. Eles entregam uma descrição do problema: "os leitores esperam meses pelos livros populares, mas os exemplares reservados ficam sem retirar na nossa estante de reservas". Detectar um problema não é o mesmo que entendê-lo. Pergunte por que acontece. Talvez os leitores sejam avisados por uma carta que chega atrasada (causa A), talvez tenham reservado semanas atrás e esquecido (causa B), talvez não exista um jeito fácil de cancelar uma reserva que não querem mais e o exemplar espera por ninguém (causa C). Cada causa leva a uma solução diferente: avisos instantâneos, lembretes ou cancelamento com um toque. Os requisitos nascem das causas que você decide atacar.'),
      L('Requirements are not just wishes. They are wishes adjusted to the real world: physical limits (the hold shelf has room for 200 books), legal rules (what a person reads must be kept private), money (the budget allows one mobile app, not two), social habits (older readers prefer a phone call), and threats (someone may try to reserve every copy of a new bestseller with fake accounts). A good analyst writes the wish and the constraints together.',
        'Los requisitos no son simples deseos. Son deseos ajustados al mundo real: límites físicos (el estante de reservas tiene lugar para 200 libros), reglas legales (lo que lee una persona debe mantenerse privado), dinero (el presupuesto alcanza para una app móvil, no dos), costumbres sociales (los lectores mayores prefieren una llamada) y amenazas (alguien puede intentar reservar todos los ejemplares de un nuevo éxito de ventas con cuentas falsas). Un buen analista escribe el deseo y las restricciones juntos.',
        'Requisitos não são apenas desejos. São desejos ajustados ao mundo real: limites físicos (a estante de reservas cabe 200 livros), regras legais (o que uma pessoa lê precisa ficar privado), dinheiro (o orçamento dá para um app, não dois), hábitos sociais (leitores mais velhos preferem uma ligação) e ameaças (alguém pode tentar reservar todos os exemplares de um novo best-seller com contas falsas). Um bom analista escreve o desejo e as restrições juntos.'),
      L('Why so much care? Because errors made in requirements are the most expensive ones. An error found while writing the requirement costs a conversation; the same error found after release can cost a hundred times more, because design, code, tests, and manuals were all built on it. Poor requirements analysis is one of the most common causes of project failure: the team builds the wrong system, fills it with features nobody uses, and finishes late and over budget. Many of those projects had good programmers; they built the wrong thing very well. Each person in the chain (client, salesperson, analyst, designer, programmer, tester) understands the need a little differently, and requirements are the shared written agreement that stops the meaning from drifting.',
        '¿Por qué tanto cuidado? Porque los errores en los requisitos son los más caros. Un error encontrado al escribir el requisito cuesta una conversación; el mismo error encontrado después de publicar puede costar cien veces más, porque el diseño, el código, las pruebas y los manuales se construyeron sobre él. Un análisis de requisitos pobre es una de las causas más comunes del fracaso de un proyecto: el equipo construye el sistema equivocado, lo llena de funciones que nadie usa y termina tarde y por encima del presupuesto. Muchos de esos proyectos tenían buenos programadores; construyeron muy bien lo que no era. Cada persona de la cadena (cliente, vendedor, analista, diseñador, programador, tester) entiende la necesidad un poco distinto, y los requisitos son el acuerdo escrito compartido que evita que el significado se desvíe.',
        'Por que tanto cuidado? Porque erros de requisitos são os mais caros. Um erro achado ao escrever o requisito custa uma conversa; o mesmo erro achado depois do lançamento pode custar cem vezes mais, porque design, código, testes e manuais foram construídos em cima dele. Uma análise de requisitos fraca é uma das causas mais comuns de fracasso de projetos: a equipe constrói o sistema errado, enche de funções que ninguém usa e termina atrasada e acima do orçamento. Muitos desses projetos tinham bons programadores; construíram muito bem a coisa errada. Cada pessoa da cadeia (cliente, vendedor, analista, designer, programador, testador) entende a necessidade de um jeito um pouco diferente, e os requisitos são o acordo escrito compartilhado que impede o significado de se perder.'),
    ],
    analogy: L('A doctor does not prescribe medicine for "I feel bad". She asks questions until she finds the cause, because headache from stress and headache from an infection need different treatments. Requirements engineering is the diagnosis; code is the treatment.',
      'Una médica no receta un medicamento para "me siento mal". Hace preguntas hasta encontrar la causa, porque el dolor de cabeza por estrés y el dolor de cabeza por una infección necesitan tratamientos distintos. La ingeniería de requisitos es el diagnóstico; el código es el tratamiento.',
      'Uma médica não receita remédio para "estou me sentindo mal". Ela faz perguntas até achar a causa, porque dor de cabeça por estresse e dor de cabeça por infecção pedem tratamentos diferentes. A engenharia de requisitos é o diagnóstico; o código é o tratamento.'),
    takeaways: [
      L('A requirement says what the system must do or how well, not how it is built.', 'Un requisito dice qué debe hacer el sistema o qué tan bien, no cómo se construye.', 'Um requisito diz o que o sistema deve fazer ou quão bem, não como é construído.'),
      L('Clients bring problems; you find the causes and derive requirements from them.', 'Los clientes traen problemas; tú encuentras las causas y derivas los requisitos de ellas.', 'Clientes trazem problemas; você encontra as causas e deriva os requisitos delas.'),
      L('Requirements = wishes adjusted to physical, legal, financial, social, and security constraints.', 'Requisitos = deseos ajustados a restricciones físicas, legales, económicas, sociales y de seguridad.', 'Requisitos = desejos ajustados a restrições físicas, legais, financeiras, sociais e de segurança.'),
      L('The later a requirements error is found, the more it costs to fix.', 'Cuanto más tarde se encuentra un error de requisitos, más cuesta corregirlo.', 'Quanto mais tarde se encontra um erro de requisitos, mais caro é corrigi-lo.'),
    ],
    check: {
      question: L('Which sentence is a requirement rather than a design decision?', '¿Qué frase es un requisito y no una decisión de diseño?', 'Qual frase é um requisito e não uma decisão de design?'),
      options: [
        L('Members can freeze their gym membership for up to 30 days a year.', 'Los socios pueden congelar su membresía del gimnasio hasta 30 días al año.', 'Os alunos podem congelar a matrícula da academia por até 30 dias por ano.'),
        L('Use a NoSQL database to store memberships.', 'Usar una base de datos NoSQL para guardar las membresías.', 'Usar um banco de dados NoSQL para guardar as matrículas.'),
        L('Write the freeze logic in a class called FreezeService.', 'Escribir la lógica de congelamiento en una clase llamada FreezeService.', 'Escrever a lógica de congelamento em uma classe chamada FreezeService.'),
      ],
      answer: 0,
      explanation: L('The first option states what users can do. The other two choose a technology or a code structure, which is design.', 'La primera opción dice qué pueden hacer los usuarios. Las otras dos eligen una tecnología o una estructura de código, que es diseño.', 'A primeira opção diz o que os usuários podem fazer. As outras duas escolhem uma tecnologia ou uma estrutura de código, o que é design.'),
    },
    pitfalls: [
      { mistake: L('Treating the first thing the client says as the requirement.', 'Tomar lo primero que dice el cliente como el requisito.', 'Tratar a primeira coisa que o cliente diz como o requisito.'),
        fix: L('Ask "why?" until you reach a cause you can act on, then write the requirement for that cause.', 'Pregunta "¿por qué?" hasta llegar a una causa sobre la que puedas actuar y escribe el requisito para esa causa.', 'Pergunte "por quê?" até chegar a uma causa sobre a qual dá para agir e escreva o requisito para essa causa.') },
      { mistake: L('Mixing solutions into requirements ("use Firebase", "add a dropdown").', 'Mezclar soluciones en los requisitos ("usar Firebase", "agregar un menú desplegable").', 'Misturar soluções nos requisitos ("usar Firebase", "colocar um dropdown").'),
        fix: L('Describe the need ("the reader picks the branch where they will collect the book") and leave the how to design.', 'Describe la necesidad ("el lector elige la sucursal donde retirará el libro") y deja el cómo para el diseño.', 'Descreva a necessidade ("o leitor escolhe a unidade onde vai retirar o livro") e deixe o como para o design.') },
    ],
    exercises: [
      { id: 'sd1w2-ex-1-1', level: 1, title: L('Problem or requirement?', '¿Problema o requisito?', 'Problema ou requisito?'),
        prompt: L('Label each line as a problem statement (P) or a requirement (R): (a) "Our delivery customers complain that food arrives cold." (b) "The app shows the estimated arrival time, updated every minute." (c) "Gym members say the 6 pm classes are always full." (d) "Members can join a waiting list for a full class."', 'Marca cada línea como planteamiento de problema (P) o requisito (R): (a) "Nuestros clientes de domicilios se quejan de que la comida llega fría." (b) "La app muestra la hora estimada de llegada, actualizada cada minuto." (c) "Los socios del gimnasio dicen que las clases de las 6 pm siempre están llenas." (d) "Los socios pueden entrar en una lista de espera para una clase llena."', 'Marque cada linha como descrição de problema (P) ou requisito (R): (a) "Nossos clientes de delivery reclamam que a comida chega fria." (b) "O app mostra o horário estimado de chegada, atualizado a cada minuto." (c) "Os alunos da academia dizem que as aulas das 18h estão sempre lotadas." (d) "Os alunos podem entrar em uma lista de espera para uma aula lotada."'),
        hint: L('A problem describes pain; a requirement describes something the system will do.', 'Un problema describe un dolor; un requisito describe algo que hará el sistema.', 'Um problema descreve uma dor; um requisito descreve algo que o sistema vai fazer.'),
        solution: L('(a) P, (b) R, (c) P, (d) R. Notice that (b) and (d) each attack one possible cause of (a) and (c).', '(a) P, (b) R, (c) P, (d) R. Observa que (b) y (d) atacan cada uno una causa posible de (a) y (c).', '(a) P, (b) R, (c) P, (d) R. Repare que (b) e (d) atacam, cada um, uma causa possível de (a) e (c).') },
      { id: 'sd1w2-ex-1-2', level: 2, title: L('Find three causes', 'Encuentra tres causas', 'Encontre três causas'),
        prompt: L('A food-delivery company says: "Many customers abandon their order before paying." Write three possible causes and one requirement for each.', 'Una empresa de domicilios dice: "Muchos clientes abandonan el pedido antes de pagar." Escribe tres causas posibles y un requisito para cada una.', 'Uma empresa de delivery diz: "Muitos clientes abandonam o pedido antes de pagar." Escreva três causas possíveis e um requisito para cada uma.'),
        hint: L('Think about price surprises, effort, and trust.', 'Piensa en sorpresas de precio, esfuerzo y confianza.', 'Pense em surpresas de preço, esforço e confiança.'),
        solution: L('Example: (1) The delivery fee appears only at the end → "The delivery fee is shown on the restaurant page before items are added." (2) Checkout asks for too much data → "Returning customers pay with a saved card in at most two taps." (3) Customers do not trust the payment page → "Payment uses a certified provider and shows its seal." Any set of distinct causes with matching requirements is fine.', 'Ejemplo: (1) El costo de envío aparece solo al final → "El costo de envío se muestra en la página del restaurante antes de agregar productos." (2) El pago pide demasiados datos → "Los clientes que ya compraron pagan con una tarjeta guardada en máximo dos toques." (3) Los clientes no confían en la página de pago → "El pago usa un proveedor certificado y muestra su sello." Cualquier grupo de causas distintas con requisitos que les correspondan es válido.', 'Exemplo: (1) A taxa de entrega só aparece no final → "A taxa de entrega aparece na página do restaurante antes de adicionar itens." (2) O checkout pede dados demais → "Clientes recorrentes pagam com um cartão salvo em no máximo dois toques." (3) Os clientes não confiam na página de pagamento → "O pagamento usa um provedor certificado e mostra seu selo." Qualquer conjunto de causas diferentes com requisitos correspondentes vale.') },
      { id: 'sd1w2-ex-1-3', level: 3, title: L('Add the constraints', 'Agrega las restricciones', 'Acrescente as restrições'),
        prompt: L('The wish is: "Readers can see everything they have ever borrowed in the library app." Name one legal, one social, and one security constraint, and rewrite the wish as a requirement that respects them.', 'El deseo es: "Los lectores pueden ver todo lo que han pedido prestado en la app de la biblioteca." Nombra una restricción legal, una social y una de seguridad, y reescribe el deseo como un requisito que las respete.', 'O desejo é: "Os leitores podem ver tudo o que já pegaram emprestado no app da biblioteca." Cite uma restrição legal, uma social e uma de segurança e reescreva o desejo como um requisito que as respeite.'),
        hint: L('Who may see a reading history? Does every reader want one kept at all?', '¿Quién puede ver un historial de lectura? ¿Todos los lectores quieren que se guarde?', 'Quem pode ver um histórico de leitura? Todo leitor quer que ele seja guardado?'),
        solution: L('Legal: what a person reads is private personal data; only the reader may see it. Social: some readers do not want any record kept, so history must be optional. Security: access requires a verified login. Requirement: "Readers who switch reading history on can see the titles they borrowed in the last 2 years after logging in; with history off, a loan leaves no record once the book is returned."', 'Legal: lo que lee una persona es un dato personal privado; solo el lector puede verlo. Social: algunos lectores no quieren que se guarde ningún registro, así que el historial debe ser opcional. Seguridad: el acceso requiere un inicio de sesión verificado. Requisito: "Los lectores que activan el historial de lectura pueden ver los títulos que pidieron en los últimos 2 años tras iniciar sesión; con el historial desactivado, un préstamo no deja registro una vez devuelto el libro."', 'Legal: o que uma pessoa lê é dado pessoal privado; só o leitor pode ver. Social: alguns leitores não querem nenhum registro guardado, então o histórico precisa ser opcional. Segurança: o acesso exige login verificado. Requisito: "Leitores que ativam o histórico de leitura podem ver os títulos que pegaram nos últimos 2 anos após fazer login; com o histórico desativado, um empréstimo não deixa registro depois que o livro é devolvido."') },
    ],
  },
  {
    id: 'sd1w2-l2-types-of-requirements',
    title: L('Types of requirements: functional, non-functional, user, and system', 'Tipos de requisitos: funcionales, no funcionales, de usuario y de sistema', 'Tipos de requisitos: funcionais, não funcionais, de usuário e de sistema'),
    minutes: 30,
    body: [
      L('Functional requirements describe behaviour: what the system does in response to an input or a situation. "The app sends a reminder 2 days before a loan is due." "A courier can mark an order as delivered." "The system issues an invoice when a membership is paid." If you can imagine a user pressing a button and seeing something happen, you are probably looking at a functional requirement.',
        'Los requisitos funcionales describen comportamiento: qué hace el sistema ante una entrada o una situación. "La app envía un recordatorio 2 días antes de que venza un préstamo." "Un repartidor puede marcar un pedido como entregado." "El sistema emite una factura cuando se paga una membresía." Si puedes imaginar a un usuario presionando un botón y viendo que pasa algo, probablemente es un requisito funcional.',
        'Requisitos funcionais descrevem comportamento: o que o sistema faz diante de uma entrada ou situação. "O app envia um lembrete 2 dias antes do vencimento de um empréstimo." "Um entregador pode marcar um pedido como entregue." "O sistema emite uma nota quando uma mensalidade é paga." Se você consegue imaginar um usuário apertando um botão e vendo algo acontecer, provavelmente é um requisito funcional.'),
      L('Non-functional requirements (also called quality requirements) describe how well the system does those things, or the limits it must respect. "Login completes in under 3 seconds." "The app works on phones from the last five years." "Payment data is encrypted." They usually apply to many functions at once, and they are often the reason a product feels good or terrible. A system can do everything it should and still fail because it is too slow, crashes, or leaks data.',
        'Los requisitos no funcionales (también llamados requisitos de calidad) describen qué tan bien hace el sistema esas cosas, o los límites que debe respetar. "El inicio de sesión termina en menos de 3 segundos." "La app funciona en celulares de los últimos cinco años." "Los datos de pago se cifran." Suelen aplicarse a muchas funciones a la vez y a menudo son la razón de que un producto se sienta bien o terrible. Un sistema puede hacer todo lo que debe y aun así fracasar por lento, por fallar o por filtrar datos.',
        'Requisitos não funcionais (também chamados de requisitos de qualidade) descrevem quão bem o sistema faz essas coisas, ou os limites que precisa respeitar. "O login termina em menos de 3 segundos." "O app funciona em celulares dos últimos cinco anos." "Os dados de pagamento são criptografados." Eles costumam valer para muitas funções ao mesmo tempo e muitas vezes são a razão de um produto parecer bom ou péssimo. Um sistema pode fazer tudo o que deve e mesmo assim fracassar por ser lento, travar ou vazar dados.'),
      L('Non-functional requirements come in three families. Product requirements limit the product itself: efficiency (performance: response time, throughput; space: memory, storage), usability (time to learn, number of errors), reliability (availability, mean time between failures), portability, and security. Organisational requirements come from the client\'s or developer\'s organisation: delivery dates, the programming language or platform to use, internal standards. External requirements come from outside: interoperability with other systems, laws (privacy, safety, accessibility), and ethics. A popular checklist is FURPS+: Functionality (including security), Usability, Reliability, Performance, Supportability, plus constraints such as design, implementation, interface, and physical limits. In everyday projects the categories you will meet most are performance (response time), security (who can see and do what), availability (percentage of uptime), usability (time and errors to finish a task), scalability (how many users or orders at the same time), and portability (which devices and operating system versions).',
        'Los requisitos no funcionales vienen en tres familias. Los requisitos del producto limitan al producto mismo: eficiencia (rendimiento: tiempo de respuesta, capacidad de procesamiento; espacio: memoria, almacenamiento), usabilidad (tiempo para aprender, número de errores), confiabilidad (disponibilidad, tiempo medio entre fallas), portabilidad y seguridad. Los requisitos organizacionales vienen de la organización del cliente o del desarrollador: fechas de entrega, el lenguaje o la plataforma a usar, estándares internos. Los requisitos externos vienen de afuera: interoperabilidad con otros sistemas, leyes (privacidad, seguridad física, accesibilidad) y ética. Una lista de verificación popular es FURPS+: Funcionalidad (incluida la seguridad), Usabilidad, Confiabilidad (Reliability), Rendimiento (Performance), Soporte (Supportability), más restricciones como diseño, implementación, interfaz y límites físicos. En los proyectos del día a día las categorías que más verás son rendimiento (tiempo de respuesta), seguridad (quién puede ver y hacer qué), disponibilidad (porcentaje de tiempo en línea), usabilidad (tiempo y errores para terminar una tarea), escalabilidad (cuántos usuarios o pedidos a la vez) y portabilidad (en qué dispositivos y versiones de sistema operativo funciona).',
        'Requisitos não funcionais vêm em três famílias. Requisitos de produto limitam o próprio produto: eficiência (desempenho: tempo de resposta, vazão; espaço: memória, armazenamento), usabilidade (tempo para aprender, número de erros), confiabilidade (disponibilidade, tempo médio entre falhas), portabilidade e segurança. Requisitos organizacionais vêm da organização do cliente ou do desenvolvedor: prazos de entrega, a linguagem ou plataforma a usar, padrões internos. Requisitos externos vêm de fora: interoperabilidade com outros sistemas, leis (privacidade, segurança física, acessibilidade) e ética. Uma lista de verificação popular é o FURPS+: Funcionalidade (incluindo segurança), Usabilidade, Confiabilidade (Reliability), Desempenho (Performance), Suportabilidade, mais restrições como design, implementação, interface e limites físicos. Nos projetos do dia a dia as categorias que você mais vai encontrar são desempenho (tempo de resposta), segurança (quem pode ver e fazer o quê), disponibilidade (porcentagem de tempo no ar), usabilidade (tempo e erros para concluir uma tarefa), escalabilidade (quantos usuários ou pedidos ao mesmo tempo) e portabilidade (em quais dispositivos e versões de sistema operacional funciona).'),
      L('A non-functional requirement is only useful if it can be measured. Turn adjectives into numbers: speed becomes response time or transactions per second; ease of use becomes training time or errors per task; reliability becomes availability (99.5% uptime per month) or mean time between failures; scalability becomes the number of users served at once (5,000 readers searching the catalogue at the same time); robustness becomes time to recover after a crash; portability becomes the list of platforms supported. "The app must be fast" cannot be tested; "the menu of a restaurant loads in under 2 seconds on a 4G connection for 95% of requests" can.',
        'Un requisito no funcional solo sirve si se puede medir. Convierte los adjetivos en números: la velocidad se vuelve tiempo de respuesta o transacciones por segundo; la facilidad de uso se vuelve tiempo de capacitación o errores por tarea; la confiabilidad se vuelve disponibilidad (99,5% del tiempo en línea al mes) o tiempo medio entre fallas; la escalabilidad se vuelve el número de usuarios atendidos a la vez (5.000 lectores buscando en el catálogo al mismo tiempo); la robustez se vuelve tiempo de recuperación tras una caída; la portabilidad se vuelve la lista de plataformas soportadas. "La app debe ser rápida" no se puede probar; "el menú de un restaurante carga en menos de 2 segundos con conexión 4G en el 95% de las solicitudes" sí.',
        'Um requisito não funcional só serve se puder ser medido. Transforme adjetivos em números: velocidade vira tempo de resposta ou transações por segundo; facilidade de uso vira tempo de treinamento ou erros por tarefa; confiabilidade vira disponibilidade (99,5% do tempo no ar por mês) ou tempo médio entre falhas; escalabilidade vira o número de usuários atendidos ao mesmo tempo (5.000 leitores buscando no catálogo simultaneamente); robustez vira tempo de recuperação após uma queda; portabilidade vira a lista de plataformas suportadas. "O app deve ser rápido" não dá para testar; "o cardápio de um restaurante carrega em menos de 2 segundos em 4G em 95% das requisições" dá.'),
      L('Requirements are also written at different levels of detail for different readers. User requirements are written in plain language (sometimes with simple diagrams) for clients and end users: "a reader can reserve a book online". System requirements expand each one into precise, detailed statements for developers and testers: "when a reserved copy is returned, the system assigns it to the first reader in the queue and notifies them; the copy waits on the hold shelf for 3 days; the same copy is never assigned to two readers". Above both sit business requirements, the organisation\'s goals ("cut the average wait for popular books by 30% this year"). Some teams also list user interface requirements separately (screens, accessibility, languages).',
        'Los requisitos también se escriben con distintos niveles de detalle para distintos lectores. Los requisitos de usuario se escriben en lenguaje sencillo (a veces con diagramas simples) para clientes y usuarios finales: "un lector puede reservar un libro en línea". Los requisitos del sistema amplían cada uno en enunciados precisos y detallados para desarrolladores y testers: "cuando se devuelve un ejemplar reservado, el sistema lo asigna al primer lector de la fila y le avisa; el ejemplar espera 3 días en el estante de reservas; el mismo ejemplar nunca se asigna a dos lectores". Por encima de ambos están los requisitos de negocio, los objetivos de la organización ("reducir un 30% este año la espera promedio de los libros populares"). Algunos equipos también listan aparte los requisitos de interfaz de usuario (pantallas, accesibilidad, idiomas).',
        'Requisitos também são escritos em níveis de detalhe diferentes para leitores diferentes. Requisitos de usuário são escritos em linguagem simples (às vezes com diagramas simples) para clientes e usuários finais: "um leitor pode reservar um livro online". Requisitos de sistema expandem cada um em enunciados precisos e detalhados para desenvolvedores e testadores: "quando um exemplar reservado é devolvido, o sistema o atribui ao primeiro leitor da fila e o avisa; o exemplar espera 3 dias na estante de reservas; o mesmo exemplar nunca é atribuído a dois leitores". Acima de ambos ficam os requisitos de negócio, os objetivos da organização ("reduzir em 30% este ano a espera média pelos livros populares"). Algumas equipes também listam à parte os requisitos de interface do usuário (telas, acessibilidade, idiomas).'),
    ],
    analogy: L('Ordering a car: "it has five seats, a trunk, and air conditioning" are functional requirements (what it does). "It does 15 km per litre, reaches 100 km/h in 10 seconds, and passes the safety test" are non-functional (how well, and under which rules). Two cars with the same features can feel completely different because of the second list.',
      'Encargar un auto: "tiene cinco asientos, maletero y aire acondicionado" son requisitos funcionales (qué hace). "Rinde 15 km por litro, llega a 100 km/h en 10 segundos y pasa la prueba de seguridad" son no funcionales (qué tan bien y bajo qué reglas). Dos autos con las mismas funciones pueden sentirse completamente distintos por la segunda lista.',
      'Encomendar um carro: "tem cinco lugares, porta-malas e ar-condicionado" são requisitos funcionais (o que ele faz). "Faz 15 km por litro, chega a 100 km/h em 10 segundos e passa no teste de segurança" são não funcionais (quão bem e sob quais regras). Dois carros com os mesmos recursos podem parecer completamente diferentes por causa da segunda lista.'),
    takeaways: [
      L('Functional = what the system does. Non-functional = how well it does it, or under which constraints.', 'Funcional = qué hace el sistema. No funcional = qué tan bien lo hace o bajo qué restricciones.', 'Funcional = o que o sistema faz. Não funcional = quão bem faz ou sob quais restrições.'),
      L('Non-functional families: product (efficiency, usability, reliability, portability, security), organisational, external.', 'Familias no funcionales: del producto (eficiencia, usabilidad, confiabilidad, portabilidad, seguridad), organizacionales y externas.', 'Famílias não funcionais: de produto (eficiência, usabilidade, confiabilidade, portabilidade, segurança), organizacionais e externas.'),
      L('FURPS+: Functionality, Usability, Reliability, Performance, Supportability, plus constraints.', 'FURPS+: Funcionalidad, Usabilidad, Confiabilidad, Rendimiento, Soporte, más restricciones.', 'FURPS+: Funcionalidade, Usabilidade, Confiabilidade, Desempenho, Suportabilidade, mais restrições.'),
      L('Every non-functional requirement needs a number you can test.', 'Todo requisito no funcional necesita un número que se pueda probar.', 'Todo requisito não funcional precisa de um número que possa ser testado.'),
      L('User requirements speak to clients; system requirements give developers the detail.', 'Los requisitos de usuario hablan a los clientes; los del sistema dan el detalle a los desarrolladores.', 'Requisitos de usuário falam com os clientes; os de sistema dão o detalhe aos desenvolvedores.'),
    ],
    check: {
      question: L('"The gym app must be available 99.9% of the time each month." Which type is it?', '"La app del gimnasio debe estar disponible el 99,9% del tiempo cada mes." ¿De qué tipo es?', '"O app da academia deve ficar disponível 99,9% do tempo a cada mês." De que tipo é?'),
      options: [
        L('Non-functional: reliability (availability)', 'No funcional: confiabilidad (disponibilidad)', 'Não funcional: confiabilidade (disponibilidade)'),
        L('Functional: a user action', 'Funcional: una acción del usuario', 'Funcional: uma ação do usuário'),
        L('Non-functional: portability', 'No funcional: portabilidad', 'Não funcional: portabilidade'),
      ],
      answer: 0,
      explanation: L('It adds no new behaviour; it sets how dependable the whole app must be, measured as availability.', 'No agrega comportamiento nuevo; fija qué tan confiable debe ser toda la app, medido como disponibilidad.', 'Não acrescenta comportamento novo; define quão confiável o app inteiro deve ser, medido como disponibilidade.'),
    },
    pitfalls: [
      { mistake: L('Writing non-functional requirements with adjectives: fast, secure, user-friendly.', 'Escribir requisitos no funcionales con adjetivos: rápido, seguro, amigable.', 'Escrever requisitos não funcionais com adjetivos: rápido, seguro, amigável.'),
        fix: L('Pick a measure and a target: "a new user books a class in under 60 seconds without help".', 'Elige una medida y una meta: "un usuario nuevo reserva una clase en menos de 60 segundos sin ayuda".', 'Escolha uma medida e uma meta: "um usuário novo reserva uma aula em menos de 60 segundos sem ajuda".') },
      { mistake: L('Calling security or privacy "functional" because there is a login screen.', 'Llamar "funcional" a la seguridad o la privacidad porque hay una pantalla de inicio de sesión.', 'Chamar segurança ou privacidade de "funcional" porque existe uma tela de login.'),
        fix: L('The login screen is functional; the rule "passwords are stored hashed and sessions expire after 15 minutes idle" is a security quality.', 'La pantalla de inicio de sesión es funcional; la regla "las contraseñas se guardan con hash y las sesiones expiran tras 15 minutos inactivas" es una cualidad de seguridad.', 'A tela de login é funcional; a regra "senhas são guardadas com hash e as sessões expiram após 15 minutos paradas" é uma qualidade de segurança.') },
    ],
    exercises: [
      { id: 'sd1w2-ex-2-1', level: 1, title: L('Sort the library list', 'Clasifica la lista de la biblioteca', 'Classifique a lista da biblioteca'),
        prompt: L('Mark each one F (functional) or NF (non-functional): (a) Librarians can mark a copy as damaged. (b) The catalogue page meets WCAG 2.1 AA accessibility. (c) Readers receive an email when a reserved book is ready. (d) The system runs on the library\'s existing Windows servers. (e) Catalogue search results appear in under 1 second.', 'Marca cada uno F (funcional) o NF (no funcional): (a) Los bibliotecarios pueden marcar un ejemplar como dañado. (b) La página del catálogo cumple la accesibilidad WCAG 2.1 AA. (c) Los lectores reciben un correo cuando un libro reservado está listo. (d) El sistema funciona en los servidores Windows que ya tiene la biblioteca. (e) Los resultados de búsqueda del catálogo aparecen en menos de 1 segundo.', 'Marque cada um F (funcional) ou NF (não funcional): (a) Bibliotecários podem marcar um exemplar como danificado. (b) A página do catálogo atende à acessibilidade WCAG 2.1 AA. (c) Leitores recebem um e-mail quando um livro reservado está disponível. (d) O sistema roda nos servidores Windows que a biblioteca já tem. (e) Os resultados da busca no catálogo aparecem em menos de 1 segundo.'),
        hint: L('Is it an action with a visible result, or a quality or limit?', '¿Es una acción con un resultado visible o una cualidad o límite?', 'É uma ação com um resultado visível ou uma qualidade ou limite?'),
        solution: L('(a) F, (b) NF (external: accessibility standard), (c) F, (d) NF (organisational: platform), (e) NF (performance).', '(a) F, (b) NF (externo: norma de accesibilidad), (c) F, (d) NF (organizacional: plataforma), (e) NF (rendimiento).', '(a) F, (b) NF (externo: norma de acessibilidade), (c) F, (d) NF (organizacional: plataforma), (e) NF (desempenho).') },
      { id: 'sd1w2-ex-2-2', level: 2, title: L('Make it measurable', 'Hazlo medible', 'Torne mensurável'),
        prompt: L('Rewrite with a measure: (a) "The delivery app should be reliable." (b) "The gym app should be easy to learn." (c) "The system should handle lots of users."', 'Reescribe con una medida: (a) "La app de domicilios debe ser confiable." (b) "La app del gimnasio debe ser fácil de aprender." (c) "El sistema debe soportar muchos usuarios."', 'Reescreva com uma medida: (a) "O app de delivery deve ser confiável." (b) "O app da academia deve ser fácil de aprender." (c) "O sistema deve aguentar muitos usuários."'),
        hint: L('Availability percentage, time to learn, concurrent users with a response time.', 'Porcentaje de disponibilidad, tiempo para aprender, usuarios simultáneos con un tiempo de respuesta.', 'Porcentagem de disponibilidade, tempo para aprender, usuários simultâneos com um tempo de resposta.'),
        solution: L('(a) "Order placement is available 99.5% of each month, and no more than 1 in 1,000 orders fails." (b) "A first-time member books a class within 2 minutes without help, in 9 of 10 usability tests." (c) "With 2,000 users online at the same time, 95% of pages load in under 2 seconds."', '(a) "La creación de pedidos está disponible el 99,5% de cada mes y falla como máximo 1 de cada 1.000 pedidos." (b) "Un socio nuevo reserva una clase en 2 minutos sin ayuda, en 9 de cada 10 pruebas de usabilidad." (c) "Con 2.000 usuarios conectados a la vez, el 95% de las páginas carga en menos de 2 segundos."', '(a) "A criação de pedidos fica disponível 99,5% de cada mês e falha no máximo 1 a cada 1.000 pedidos." (b) "Um aluno novo reserva uma aula em até 2 minutos sem ajuda, em 9 de cada 10 testes de usabilidade." (c) "Com 2.000 usuários conectados ao mesmo tempo, 95% das páginas carregam em menos de 2 segundos."') },
      { id: 'sd1w2-ex-2-3', level: 3, title: L('From user to system requirement', 'De requisito de usuario a requisito del sistema', 'De requisito de usuário a requisito de sistema'),
        prompt: L('Expand the user requirement "A gym member can book a class" into four precise system requirements.', 'Amplía el requisito de usuario "Un socio del gimnasio puede reservar una clase" en cuatro requisitos del sistema precisos.', 'Expanda o requisito de usuário "Um aluno da academia pode reservar uma aula" em quatro requisitos de sistema precisos.'),
        hint: L('Think about who can book, how far ahead, capacity, and what happens when a class is full.', 'Piensa en quién puede reservar, con cuánta anticipación, el cupo y qué pasa si la clase está llena.', 'Pense em quem pode reservar, com quanta antecedência, a capacidade e o que acontece se a aula lotar.'),
        solution: L('Example: (1) Only members with an active plan can book. (2) Classes open for booking 7 days ahead and close 30 minutes before start. (3) A class accepts at most its room capacity; when full, the member is offered the waiting list. (4) A member can hold at most 2 future bookings for the same class type.', 'Ejemplo: (1) Solo los socios con un plan activo pueden reservar. (2) Las clases se abren 7 días antes y se cierran 30 minutos antes de empezar. (3) Una clase acepta como máximo el cupo de la sala; si está llena, se ofrece la lista de espera. (4) Un socio puede tener como máximo 2 reservas futuras del mismo tipo de clase.', 'Exemplo: (1) Só alunos com plano ativo podem reservar. (2) As aulas abrem para reserva 7 dias antes e fecham 30 minutos antes do início. (3) Uma aula aceita no máximo a capacidade da sala; lotada, o aluno recebe a opção da lista de espera. (4) Um aluno pode ter no máximo 2 reservas futuras do mesmo tipo de aula.') },
    ],
  },
  {
    id: 'sd1w2-l3-process-and-people',
    title: L('The requirements engineering process and its people', 'El proceso de ingeniería de requisitos y sus personas', 'O processo de engenharia de requisitos e suas pessoas'),
    minutes: 25,
    diagram: 'requirements',
    body: [
      L('Requirements engineering is the set of activities used to discover, write down, check, and maintain what a system must do. It acts as a bridge between the real-world needs of clients and users and what software technology can offer. Different books slice it differently, but the same core activities always appear: a feasibility study, elicitation (gathering), analysis (refining and negotiating), specification (writing down), validation (checking with the client), and management (handling change). The diagram shows the classic sequence; in practice the activities loop and overlap.',
        'La ingeniería de requisitos es el conjunto de actividades para descubrir, documentar, verificar y mantener lo que un sistema debe hacer. Funciona como puente entre las necesidades reales de clientes y usuarios y lo que la tecnología de software puede ofrecer. Cada libro la divide distinto, pero siempre aparecen las mismas actividades centrales: un estudio de factibilidad, la elicitación (recolección), el análisis (refinar y negociar), la especificación (documentar), la validación (verificar con el cliente) y la gestión (manejar los cambios). El diagrama muestra la secuencia clásica; en la práctica las actividades se repiten y se solapan.',
        'Engenharia de requisitos é o conjunto de atividades para descobrir, documentar, verificar e manter o que um sistema deve fazer. Ela funciona como ponte entre as necessidades reais de clientes e usuários e o que a tecnologia de software pode oferecer. Cada livro a divide de um jeito, mas as mesmas atividades centrais sempre aparecem: estudo de viabilidade, elicitação (levantamento), análise (refinar e negociar), especificação (documentar), validação (conferir com o cliente) e gestão (lidar com mudanças). O diagrama mostra a sequência clássica; na prática as atividades se repetem e se sobrepõem.'),
      L('The feasibility study answers one question early: can the users\' needs be met with the technology, time, and budget available? A short report says go, change scope, or stop. Elicitation then collects needs from people, documents, and existing systems. Analysis refines what was gathered, removes contradictions, checks that it is realistic, and decides priorities with the client. Specification writes the agreed requirements in a clear, shared form: a requirements document, a backlog of user stories, or both. Validation shows the result to the client and asks: is this really what you need? Management records every change, its reason, and its approver, for the life of the product.',
        'El estudio de factibilidad responde temprano una pregunta: ¿se pueden cubrir las necesidades de los usuarios con la tecnología, el tiempo y el presupuesto disponibles? Un informe breve dice seguir, cambiar el alcance o parar. Luego la elicitación recoge necesidades de personas, documentos y sistemas existentes. El análisis refina lo recogido, elimina contradicciones, verifica que sea realista y decide prioridades con el cliente. La especificación escribe los requisitos acordados en una forma clara y compartida: un documento de requisitos, un backlog de historias de usuario o ambos. La validación muestra el resultado al cliente y pregunta: ¿esto es realmente lo que necesitas? La gestión registra cada cambio, su motivo y quién lo aprueba, durante toda la vida del producto.',
        'O estudo de viabilidade responde cedo a uma pergunta: dá para atender às necessidades dos usuários com a tecnologia, o tempo e o orçamento disponíveis? Um relatório curto diz seguir, mudar o escopo ou parar. Depois a elicitação coleta necessidades de pessoas, documentos e sistemas existentes. A análise refina o que foi coletado, remove contradições, verifica se é realista e decide prioridades com o cliente. A especificação escreve os requisitos acordados de forma clara e compartilhada: um documento de requisitos, um backlog de histórias de usuário ou ambos. A validação mostra o resultado ao cliente e pergunta: é isso mesmo que você precisa? A gestão registra cada mudança, o motivo e quem aprovou, durante toda a vida do produto.'),
      L('A stakeholder is anyone affected by the system or who influences its requirements, directly or indirectly. For a public library system: readers, desk staff, librarians, the city council that pays, the IT staff who will maintain it, the e-book distributor whose licences limit lending, other libraries in the regional loan network, and the data-protection authority whose privacy rules apply. Stakeholders want different things (the council wants each book to circulate faster, readers want longer loans), and some never touch the app but can still block it, like a regulator. Missing a stakeholder means missing requirements.',
        'Un interesado (stakeholder) es cualquiera afectado por el sistema o que influye en sus requisitos, directa o indirectamente. Para el sistema de una biblioteca pública: lectores, personal de mostrador, bibliotecarios, el municipio que paga, el personal de TI que lo mantendrá, el distribuidor de libros electrónicos cuyas licencias limitan los préstamos, las otras bibliotecas de la red regional de préstamos y la autoridad de protección de datos cuyas reglas de privacidad se aplican. Los interesados quieren cosas distintas (el municipio quiere que cada libro circule más rápido, los lectores quieren préstamos más largos) y algunos nunca tocan la app pero igual pueden bloquearla, como un regulador. Olvidar a un interesado es olvidar requisitos.',
        'Um stakeholder (parte interessada) é qualquer pessoa afetada pelo sistema ou que influencia seus requisitos, direta ou indiretamente. Para o sistema de uma biblioteca pública: leitores, atendentes do balcão, bibliotecários, a prefeitura que paga, a equipe de TI que vai manter o sistema, a distribuidora de e-books cujas licenças limitam os empréstimos, as outras bibliotecas da rede regional de empréstimos e a autoridade de proteção de dados cujas regras de privacidade se aplicam. Stakeholders querem coisas diferentes (a prefeitura quer que cada livro circule mais rápido, os leitores querem empréstimos mais longos) e alguns nunca usam o app mas mesmo assim podem bloqueá-lo, como um órgão regulador. Esquecer um stakeholder é esquecer requisitos.'),
      L('The requirements engineer (or analyst) is an agent of change. Starting from a vague sense of a problem or opportunity, the analyst asks: what is the problem (the boundaries)? Where does it happen (the context)? Whose problem is it (the stakeholders)? Why must it be solved (their goals)? How could software help (scenarios)? When must it be solved (constraints)? What could stop us (risks)? Good analysts communicate, observe, organise, and learn the domain until they can talk like an insider. The client, in turn, must explain the business, be clear about the problem, review documents, report changes, and accept that new wishes change cost and time.',
        'El ingeniero de requisitos (o analista) es un agente de cambio. A partir de una idea vaga de un problema u oportunidad, el analista pregunta: ¿cuál es el problema (los límites)? ¿Dónde ocurre (el contexto)? ¿De quién es el problema (los interesados)? ¿Por qué hay que resolverlo (sus objetivos)? ¿Cómo podría ayudar el software (escenarios)? ¿Cuándo hay que resolverlo (restricciones)? ¿Qué podría impedirlo (riesgos)? Los buenos analistas comunican, observan, organizan y aprenden el dominio hasta poder hablar como alguien de adentro. El cliente, a su vez, debe explicar el negocio, ser claro sobre el problema, revisar documentos, avisar los cambios y aceptar que los deseos nuevos cambian costo y tiempo.',
        'O engenheiro de requisitos (ou analista) é um agente de mudança. A partir de uma ideia vaga de um problema ou oportunidade, o analista pergunta: qual é o problema (os limites)? Onde acontece (o contexto)? De quem é o problema (os stakeholders)? Por que precisa ser resolvido (seus objetivos)? Como o software poderia ajudar (cenários)? Quando precisa ser resolvido (restrições)? O que poderia nos impedir (riscos)? Bons analistas comunicam, observam, organizam e aprendem o domínio até conseguirem falar como alguém de dentro. O cliente, por sua vez, precisa explicar o negócio, ser claro sobre o problema, revisar documentos, avisar mudanças e aceitar que desejos novos mudam custo e prazo.'),
    ],
    analogy: L('Planning a wedding: first you check what the budget allows (feasibility), then you ask both families what they want (elicitation), resolve "outdoor" versus "grandma cannot walk on grass" (analysis and negotiation), write the plan (specification), show it to the couple (validation), and keep a log when the guest list changes for the fifth time (management).',
      'Organizar una boda: primero ves qué permite el presupuesto (factibilidad), luego preguntas a ambas familias qué quieren (elicitación), resuelves "al aire libre" contra "la abuela no puede caminar sobre el césped" (análisis y negociación), escribes el plan (especificación), se lo muestras a los novios (validación) y llevas un registro cuando la lista de invitados cambia por quinta vez (gestión).',
      'Organizar um casamento: primeiro você vê o que o orçamento permite (viabilidade), depois pergunta às duas famílias o que querem (elicitação), resolve "ao ar livre" contra "a avó não pode andar na grama" (análise e negociação), escreve o plano (especificação), mostra aos noivos (validação) e mantém um registro quando a lista de convidados muda pela quinta vez (gestão).'),
    takeaways: [
      L('Core activities: feasibility, elicitation, analysis, specification, validation, management.', 'Actividades centrales: factibilidad, elicitación, análisis, especificación, validación y gestión.', 'Atividades centrais: viabilidade, elicitação, análise, especificação, validação e gestão.'),
      L('The activities overlap and repeat; management runs the whole time.', 'Las actividades se solapan y se repiten; la gestión ocurre todo el tiempo.', 'As atividades se sobrepõem e se repetem; a gestão acontece o tempo todo.'),
      L('A stakeholder is anyone affected by the system or able to influence it, even without using it.', 'Un interesado es cualquiera afectado por el sistema o capaz de influir en él, aunque no lo use.', 'Um stakeholder é qualquer um afetado pelo sistema ou capaz de influenciá-lo, mesmo sem usá-lo.'),
      L('The analyst asks what, where, whose, why, how, when, and what could stop us.', 'El analista pregunta qué, dónde, de quién, por qué, cómo, cuándo y qué podría impedirlo.', 'O analista pergunta o quê, onde, de quem, por quê, como, quando e o que pode impedir.'),
    ],
    check: {
      question: L('In a food-delivery app, which of these is a stakeholder who may never open the app?', 'En una app de domicilios, ¿cuál de estos es un interesado que quizá nunca abra la app?', 'Em um app de delivery, qual destes é um stakeholder que talvez nunca abra o app?'),
      options: [
        L('The city\'s food-safety inspector', 'El inspector de seguridad alimentaria de la ciudad', 'O fiscal de vigilância sanitária da cidade'),
        L('The customer ordering dinner', 'El cliente que pide la cena', 'O cliente que pede o jantar'),
        L('The courier delivering the order', 'El repartidor que entrega el pedido', 'O entregador que leva o pedido'),
      ],
      answer: 0,
      explanation: L('Regulators are stakeholders: their rules (for example, temperature limits for food transport) become requirements even though they do not use the app.', 'Los reguladores son interesados: sus reglas (por ejemplo, límites de temperatura para transportar comida) se vuelven requisitos aunque no usen la app.', 'Órgãos reguladores são stakeholders: suas regras (por exemplo, limites de temperatura para transportar comida) viram requisitos mesmo que eles não usem o app.'),
    },
    pitfalls: [
      { mistake: L('Interviewing only the person who pays.', 'Entrevistar solo a quien paga.', 'Entrevistar só quem paga.'),
        fix: L('List every stakeholder group first; desk staff know problems the council has never seen.', 'Lista primero todos los grupos de interesados; el personal de mostrador conoce problemas que el municipio nunca ha visto.', 'Liste primeiro todos os grupos de stakeholders; os atendentes do balcão conhecem problemas que a prefeitura nunca viu.') },
      { mistake: L('Treating the process as a one-time phase at the start.', 'Tratar el proceso como una fase única al inicio.', 'Tratar o processo como uma fase única no início.'),
        fix: L('Expect to elicit, analyse, and validate again in every iteration.', 'Espera volver a elicitar, analizar y validar en cada iteración.', 'Conte com elicitar, analisar e validar de novo a cada iteração.') },
    ],
    exercises: [
      { id: 'sd1w2-ex-3-1', level: 1, title: L('List the stakeholders', 'Lista los interesados', 'Liste os stakeholders'),
        prompt: L('List at least six stakeholders of a gym membership app and say what each one cares about.', 'Lista al menos seis interesados de una app de membresías de gimnasio y di qué le importa a cada uno.', 'Liste pelo menos seis stakeholders de um app de matrículas de academia e diga com o que cada um se importa.'),
        hint: L('Include people who use it, people who pay, people who maintain it, and outside bodies.', 'Incluye a quienes la usan, a quienes pagan, a quienes la mantienen y a organismos externos.', 'Inclua quem usa, quem paga, quem mantém e órgãos externos.'),
        solution: L('Members (easy booking), trainers (their class lists), front-desk staff (quick check-in), the owner (renewals and revenue), the payment provider (correct card handling), IT support (easy maintenance), the data-protection authority (privacy of member data). Six or more sensible ones is a pass.', 'Socios (reservar fácil), entrenadores (sus listas de clase), personal de recepción (registro de entrada rápido), el dueño (renovaciones e ingresos), el proveedor de pagos (manejo correcto de tarjetas), soporte de TI (mantenimiento fácil), la autoridad de protección de datos (privacidad de los datos de los socios). Seis o más razonables es suficiente.', 'Alunos (reservar fácil), instrutores (suas listas de aula), recepção (check-in rápido), o dono (renovações e receita), o provedor de pagamento (tratamento correto dos cartões), suporte de TI (manutenção fácil), a autoridade de proteção de dados (privacidade dos dados dos alunos). Seis ou mais razoáveis é suficiente.') },
      { id: 'sd1w2-ex-3-2', level: 2, title: L('Name the activity', 'Nombra la actividad', 'Nomeie a atividade'),
        prompt: L('Which activity is each? (a) Showing a clickable mock-up to desk staff to confirm the lending flow. (b) Checking if an SMS gateway fits the budget. (c) Logging that the hold pickup window changed from 7 to 3 days, approved by the head librarian. (d) Sitting at the lending desk for a morning to watch how loans happen.', '¿Qué actividad es cada una? (a) Mostrar una maqueta navegable al personal de mostrador para confirmar el flujo de préstamo. (b) Revisar si un servicio de SMS cabe en el presupuesto. (c) Registrar que el plazo para retirar una reserva cambió de 7 a 3 días, aprobado por la bibliotecaria jefa. (d) Sentarse una mañana en el mostrador de préstamos para observar cómo se hacen los préstamos.', 'Qual atividade é cada uma? (a) Mostrar um protótipo clicável aos atendentes do balcão para confirmar o fluxo de empréstimo. (b) Verificar se um serviço de SMS cabe no orçamento. (c) Registrar que o prazo para retirar uma reserva mudou de 7 para 3 dias, aprovado pela bibliotecária-chefe. (d) Passar uma manhã no balcão de empréstimos observando como os empréstimos acontecem.'),
        hint: L('Check with the client, check if possible, record a change, gather facts.', 'Verificar con el cliente, verificar si es posible, registrar un cambio, recoger hechos.', 'Conferir com o cliente, conferir se é possível, registrar uma mudança, coletar fatos.'),
        solution: L('(a) Validation. (b) Feasibility. (c) Management. (d) Elicitation (observation).', '(a) Validación. (b) Factibilidad. (c) Gestión. (d) Elicitación (observación).', '(a) Validação. (b) Viabilidade. (c) Gestão. (d) Elicitação (observação).') },
    ],
  },
  {
    id: 'sd1w2-l4-elicitation-analysis',
    title: L('Elicitation and analysis: gathering and refining needs', 'Elicitación y análisis: recoger y refinar necesidades', 'Elicitação e análise: coletar e refinar necessidades'),
    minutes: 30,
    diagram: 'context',
    body: [
      L('Elicitation means drawing requirements out of people and sources. Each technique has strengths. Interviews (open or with a script) give depth and let you follow surprises. Questionnaires reach many users cheaply but give shallow answers. Observation (watching people do the real work) reveals steps nobody thinks to mention. Workshops and brainstorming put several stakeholders in one room to agree faster. Document analysis mines forms, manuals, and regulations. Prototypes (sketches or clickable mock-ups) let users react to something concrete, which is often easier than describing a need. Scenarios walk through one concrete situation from start to end.',
        'Elicitar significa sacar los requisitos de las personas y las fuentes. Cada técnica tiene sus fortalezas. Las entrevistas (abiertas o con guion) dan profundidad y permiten seguir las sorpresas. Los cuestionarios llegan a muchos usuarios a bajo costo, pero dan respuestas superficiales. La observación (ver a la gente hacer el trabajo real) revela pasos que nadie piensa mencionar. Los talleres y la lluvia de ideas reúnen a varios interesados en una sala para ponerse de acuerdo más rápido. El análisis de documentos aprovecha formularios, manuales y normas. Los prototipos (bocetos o maquetas navegables) permiten que los usuarios reaccionen ante algo concreto, lo que suele ser más fácil que describir una necesidad. Los escenarios recorren una situación concreta de principio a fin.',
        'Elicitar significa extrair os requisitos das pessoas e das fontes. Cada técnica tem seus pontos fortes. Entrevistas (abertas ou com roteiro) dão profundidade e permitem seguir as surpresas. Questionários alcançam muitos usuários a baixo custo, mas dão respostas rasas. A observação (ver as pessoas fazendo o trabalho real) revela passos que ninguém pensa em mencionar. Workshops e brainstorming reúnem vários stakeholders em uma sala para chegar a um acordo mais rápido. A análise de documentos aproveita formulários, manuais e normas. Protótipos (rascunhos ou telas clicáveis) deixam os usuários reagirem a algo concreto, o que costuma ser mais fácil do que descrever uma necessidade. Cenários percorrem uma situação concreta do começo ao fim.'),
      L('Elicitation is hard for three classic reasons. Scope: the boundary of the system is unclear, so draw a context diagram like the one above (the system in the middle, the outside actors around it, and the data they exchange) and write what is in and what is out. Understanding: users may not know what they need, use their own jargon, or describe goals at a very high level ("make deliveries better"). Volatility: needs change between meetings, so record what was agreed. Combine written communication (permanent, easy to share and review, but easy to misread) with conversation (immediate feedback, shared understanding with less effort).',
        'La elicitación es difícil por tres razones clásicas. Alcance: el límite del sistema no está claro, así que dibuja un diagrama de contexto como el de arriba (el sistema al centro, los actores externos alrededor y los datos que intercambian) y escribe qué entra y qué no. Comprensión: los usuarios pueden no saber lo que necesitan, usar su propia jerga o describir objetivos a un nivel muy alto ("mejorar los domicilios"). Volatilidad: las necesidades cambian entre reuniones, así que registra lo acordado. Combina la comunicación escrita (permanente, fácil de compartir y revisar, pero fácil de malinterpretar) con la conversación (retroalimentación inmediata, comprensión compartida con menos esfuerzo).',
        'A elicitação é difícil por três motivos clássicos. Escopo: o limite do sistema não está claro, então desenhe um diagrama de contexto como o de cima (o sistema no meio, os atores externos ao redor e os dados que trocam) e escreva o que entra e o que fica fora. Entendimento: os usuários podem não saber do que precisam, usar o próprio jargão ou descrever objetivos em nível muito alto ("melhorar as entregas"). Volatilidade: as necessidades mudam entre reuniões, então registre o que foi combinado. Combine comunicação escrita (permanente, fácil de compartilhar e revisar, mas fácil de entender errado) com conversa (retorno imediato, entendimento compartilhado com menos esforço).'),
      L('Analysis turns the raw pile into a set you can build. You refine vague items into precise ones, split big ones, merge duplicates, find conflicts, and check that each one is feasible and realistic. Take the requirement "a customer can track the courier". Analysis asks: how often does the position update? What does the customer see if the courier\'s phone loses signal? Is tracking shown before the restaurant hands over the food? One line can grow into several, such as "position refreshes every 15 seconds" and "after 2 minutes without signal, the map shows the last known position and a notice".',
        'El análisis convierte el montón en bruto en un conjunto que se puede construir. Refinas lo vago en algo preciso, divides lo grande, unes duplicados, encuentras conflictos y verificas que cada uno sea factible y realista. Toma el requisito "un cliente puede seguir al repartidor". El análisis pregunta: ¿cada cuánto se actualiza la posición? ¿Qué ve el cliente si el celular del repartidor pierde la señal? ¿Se muestra el seguimiento antes de que el restaurante entregue la comida? Una línea puede crecer en varias, como "la posición se actualiza cada 15 segundos" y "tras 2 minutos sin señal, el mapa muestra la última posición conocida y un aviso".',
        'A análise transforma a pilha bruta em um conjunto que dá para construir. Você refina o vago em algo preciso, divide o que é grande, junta duplicados, encontra conflitos e verifica se cada item é viável e realista. Pegue o requisito "um cliente pode acompanhar o entregador". A análise pergunta: de quanto em quanto tempo a posição atualiza? O que o cliente vê se o celular do entregador perder sinal? O rastreamento aparece antes de o restaurante entregar a comida? Uma linha pode virar várias, como "a posição atualiza a cada 15 segundos" e "após 2 minutos sem sinal, o mapa mostra a última posição conhecida e um aviso".'),
      L('Analysis also uncovers business policies: decisions that belong to the client, not to the programmer. How many wrong PIN attempts before an account is locked? How many minutes late can a gym member arrive before losing the spot? How many days does a reserved book wait on the hold shelf before it passes to the next reader? Make each policy explicit, for two reasons: the client and other stakeholders get to decide it, and the code can keep it in one configurable place, because policies change. Finally, negotiation settles conflicts (the council wants 14-day loans so books circulate, readers want 28) and priorities: what must be in the first release, and what can wait. Analysis should not be endless, but it should never be skipped.',
        'El análisis también descubre políticas de negocio: decisiones que le corresponden al cliente, no al programador. ¿Cuántos intentos de PIN incorrectos antes de bloquear una cuenta? ¿Cuántos minutos tarde puede llegar un socio del gimnasio antes de perder su lugar? ¿Cuántos días espera un libro reservado en el estante antes de pasar al siguiente lector? Haz explícita cada política, por dos razones: el cliente y otros interesados pueden decidirla, y el código puede mantenerla en un solo lugar configurable, porque las políticas cambian. Por último, la negociación resuelve conflictos (el municipio quiere préstamos de 14 días para que los libros circulen, los lectores quieren 28) y prioridades: qué debe estar en la primera versión y qué puede esperar. El análisis no debe ser interminable, pero nunca debe saltarse.',
        'A análise também revela políticas de negócio: decisões que cabem ao cliente, não ao programador. Quantas tentativas erradas de PIN antes de bloquear a conta? Quantos minutos de atraso um aluno da academia pode ter antes de perder a vaga? Quantos dias um livro reservado espera na estante antes de passar ao próximo leitor? Deixe cada política explícita, por dois motivos: o cliente e outros stakeholders podem decidi-la, e o código pode mantê-la em um único lugar configurável, porque políticas mudam. Por fim, a negociação resolve conflitos (a prefeitura quer empréstimos de 14 dias para os livros circularem, os leitores querem 28) e prioridades: o que precisa estar na primeira versão e o que pode esperar. A análise não deve ser infinita, mas nunca deve ser pulada.'),
    ],
    analogy: L('A journalist covering a story interviews witnesses (interviews), reads police reports (document analysis), visits the scene (observation), and then cross-checks the versions to remove contradictions before publishing (analysis). Publishing the first witness\'s version unchecked is how wrong stories, and wrong software, get made.',
      'Una periodista que cubre una noticia entrevista testigos (entrevistas), lee informes policiales (análisis de documentos), visita el lugar (observación) y luego contrasta las versiones para eliminar contradicciones antes de publicar (análisis). Publicar la versión del primer testigo sin verificar es como se hacen las noticias equivocadas, y el software equivocado.',
      'Uma jornalista cobrindo uma notícia entrevista testemunhas (entrevistas), lê boletins de ocorrência (análise de documentos), visita o local (observação) e depois confronta as versões para eliminar contradições antes de publicar (análise). Publicar a versão da primeira testemunha sem checar é como nascem notícias erradas, e software errado.'),
    takeaways: [
      L('Techniques: interviews, questionnaires, observation, workshops, document analysis, prototypes, scenarios.', 'Técnicas: entrevistas, cuestionarios, observación, talleres, análisis de documentos, prototipos, escenarios.', 'Técnicas: entrevistas, questionários, observação, workshops, análise de documentos, protótipos, cenários.'),
      L('Three difficulties: scope, understanding, and volatility.', 'Tres dificultades: alcance, comprensión y volatilidad.', 'Três dificuldades: escopo, entendimento e volatilidade.'),
      L('Analysis refines, splits, merges, finds conflicts, and checks feasibility.', 'El análisis refina, divide, une, encuentra conflictos y verifica la factibilidad.', 'A análise refina, divide, junta, encontra conflitos e verifica a viabilidade.'),
      L('Business policies are the client\'s decisions: make them explicit and keep them configurable.', 'Las políticas de negocio son decisiones del cliente: hazlas explícitas y mantenlas configurables.', 'Políticas de negócio são decisões do cliente: deixe-as explícitas e configuráveis.'),
    ],
    check: {
      question: L('Library desk staff say lending a book is "simple", but you suspect they skip steps they no longer notice. Which technique fits best?', 'El personal de mostrador de la biblioteca dice que prestar un libro es "simple", pero sospechas que omiten pasos que ya no notan. ¿Qué técnica encaja mejor?', 'Os atendentes do balcão da biblioteca dizem que emprestar um livro é "simples", mas você desconfia que eles pulam passos que nem percebem mais. Qual técnica encaixa melhor?'),
      options: [
        L('Observation of real work at the lending desk', 'Observación del trabajo real en el mostrador de préstamos', 'Observação do trabalho real no balcão de empréstimos'),
        L('An online questionnaire', 'Un cuestionario en línea', 'Um questionário online'),
        L('Reading the library\'s event brochure', 'Leer el folleto de eventos de la biblioteca', 'Ler o folheto de eventos da biblioteca'),
      ],
      answer: 0,
      explanation: L('Habitual steps are invisible to the people who do them; watching the real work reveals them. A questionnaire would repeat "it is simple".', 'Los pasos habituales son invisibles para quienes los hacen; observar el trabajo real los revela. Un cuestionario repetiría "es simple".', 'Passos habituais são invisíveis para quem os faz; observar o trabalho real os revela. Um questionário repetiria "é simples".'),
    },
    pitfalls: [
      { mistake: L('Letting the programmer silently choose a business rule (for example, "lock after 5 attempts").', 'Dejar que el programador elija en silencio una regla de negocio (por ejemplo, "bloquear tras 5 intentos").', 'Deixar o programador escolher em silêncio uma regra de negócio (por exemplo, "bloquear após 5 tentativas").'),
        fix: L('Write it as an open policy question for the client and keep the value configurable.', 'Escríbela como una pregunta de política abierta para el cliente y deja el valor configurable.', 'Escreva como uma pergunta de política aberta para o cliente e deixe o valor configurável.') },
      { mistake: L('Using a questionnaire to discover needs nobody has put into words yet.', 'Usar un cuestionario para descubrir necesidades que nadie ha puesto en palabras.', 'Usar um questionário para descobrir necessidades que ninguém colocou em palavras ainda.'),
        fix: L('Start with interviews, observation, or a prototype; use questionnaires later to confirm with many users.', 'Empieza con entrevistas, observación o un prototipo; usa cuestionarios después para confirmar con muchos usuarios.', 'Comece com entrevistas, observação ou um protótipo; use questionários depois para confirmar com muitos usuários.') },
    ],
    exercises: [
      { id: 'sd1w2-ex-4-1', level: 1, title: L('Choose the technique', 'Elige la técnica', 'Escolha a técnica'),
        prompt: L('Pick a technique for each: (a) You need the opinion of 3,000 gym members about class times. (b) You must learn the rules for keeping readers\' personal data. (c) Couriers cannot describe what slows them down at restaurants. (d) The owner cannot imagine how the new booking screen should look.', 'Elige una técnica para cada caso: (a) Necesitas la opinión de 3.000 socios del gimnasio sobre los horarios de clase. (b) Debes conocer las reglas para guardar los datos personales de los lectores. (c) Los repartidores no saben describir qué los retrasa en los restaurantes. (d) El dueño no logra imaginar cómo debe verse la nueva pantalla de reservas.', 'Escolha uma técnica para cada caso: (a) Você precisa da opinião de 3.000 alunos da academia sobre horários de aula. (b) Você precisa conhecer as regras para guardar os dados pessoais dos leitores. (c) Os entregadores não sabem descrever o que os atrasa nos restaurantes. (d) O dono não consegue imaginar como deve ficar a nova tela de reservas.'),
        hint: L('Many people, written rules, invisible habits, need something concrete.', 'Muchas personas, reglas escritas, hábitos invisibles, necesidad de algo concreto.', 'Muitas pessoas, regras escritas, hábitos invisíveis, necessidade de algo concreto.'),
        solution: L('(a) Questionnaire. (b) Document analysis (laws and regulations). (c) Observation (ride along or wait at pickup points). (d) Prototype (sketch or clickable mock-up).', '(a) Cuestionario. (b) Análisis de documentos (leyes y normas). (c) Observación (acompañarlos o esperar en los puntos de recogida). (d) Prototipo (boceto o maqueta navegable).', '(a) Questionário. (b) Análise de documentos (leis e normas). (c) Observação (acompanhá-los ou esperar nos pontos de coleta). (d) Protótipo (rascunho ou tela clicável).') },
      { id: 'sd1w2-ex-4-2', level: 2, title: L('Find the hidden policies', 'Encuentra las políticas ocultas', 'Encontre as políticas escondidas'),
        prompt: L('Requirement: "Members who miss classes are penalised." List three business-policy questions the client must answer before anyone codes it.', 'Requisito: "Los socios que faltan a clases son penalizados." Lista tres preguntas de política de negocio que el cliente debe responder antes de programarlo.', 'Requisito: "Alunos que faltam às aulas são penalizados." Liste três perguntas de política de negócio que o cliente precisa responder antes de alguém programar.'),
        hint: L('What counts as missing? What is the penalty? Are there exceptions?', '¿Qué cuenta como faltar? ¿Cuál es la penalización? ¿Hay excepciones?', 'O que conta como falta? Qual é a penalidade? Existem exceções?'),
        solution: L('Examples: How late can a member cancel before it counts as a no-show? How many no-shows trigger a penalty, and in what period? Is the penalty a fee, a booking ban for N days, or a warning? Are medical excuses accepted? Each answer becomes a configurable value.', 'Ejemplos: ¿Con cuánta anticipación mínima se puede cancelar antes de que cuente como inasistencia? ¿Cuántas inasistencias activan la penalización y en qué período? ¿La penalización es un cobro, una prohibición de reservar por N días o una advertencia? ¿Se aceptan excusas médicas? Cada respuesta se vuelve un valor configurable.', 'Exemplos: Com quanta antecedência mínima dá para cancelar antes de contar como falta? Quantas faltas ativam a penalidade e em que período? A penalidade é uma multa, um bloqueio de reservas por N dias ou um aviso? Atestados médicos são aceitos? Cada resposta vira um valor configurável.') },
      { id: 'sd1w2-ex-4-3', level: 3, title: L('Draw the boundary', 'Dibuja el límite', 'Desenhe o limite'),
        prompt: L('Describe in words a context diagram for a public library system: the system, at least four external actors, and one data flow each way for two of them. Then write one "in scope" and one "out of scope" statement.', 'Describe con palabras un diagrama de contexto para el sistema de una biblioteca pública: el sistema, al menos cuatro actores externos y un flujo de datos en cada sentido para dos de ellos. Luego escribe una frase "dentro del alcance" y una "fuera del alcance".', 'Descreva em palavras um diagrama de contexto para o sistema de uma biblioteca pública: o sistema, pelo menos quatro atores externos e um fluxo de dados em cada sentido para dois deles. Depois escreva uma frase "dentro do escopo" e uma "fora do escopo".'),
        hint: L('Actors are outside the system: people, other systems, organisations.', 'Los actores están fuera del sistema: personas, otros sistemas, organizaciones.', 'Os atores ficam fora do sistema: pessoas, outros sistemas, organizações.'),
        solution: L('System in the centre. Actors: reader, librarian, email/SMS provider, regional library network, e-book distributor. Reader → system: reservation request; system → reader: "your book is ready" notice. Regional network → system: request to lend a copy; system → regional network: copy availability. In scope: "catalogue search, reservations, loans, renewals, and reminders". Out of scope: "buying new books and staff payroll".', 'Sistema al centro. Actores: lector, bibliotecario, proveedor de correo/SMS, red regional de bibliotecas, distribuidor de libros electrónicos. Lector → sistema: solicitud de reserva; sistema → lector: aviso "tu libro está listo". Red regional → sistema: pedido de préstamo de un ejemplar; sistema → red regional: disponibilidad del ejemplar. Dentro del alcance: "búsqueda en el catálogo, reservas, préstamos, renovaciones y recordatorios". Fuera del alcance: "compra de libros nuevos y nómina del personal".', 'Sistema no centro. Atores: leitor, bibliotecário, provedor de e-mail/SMS, rede regional de bibliotecas, distribuidora de e-books. Leitor → sistema: pedido de reserva; sistema → leitor: aviso "seu livro está disponível". Rede regional → sistema: pedido de empréstimo de um exemplar; sistema → rede regional: disponibilidade do exemplar. Dentro do escopo: "busca no catálogo, reservas, empréstimos, renovações e lembretes". Fora do escopo: "compra de livros novos e folha de pagamento da equipe".') },
    ],
  },
];

export const sd1Week2Lessons: Lesson[] = [...lessonsA, ...sd1Week2LessonsB];
